      "Bir akşam, diğer tüm yıldızlardan daha parlak parlayan özel bir yıldız gördü. Yumuşak, gökkuşağı renkleriyle atıyordu, Kemal daha önce hiç böyle bir şey görmemişti. Sanki ona yaramazca göz kırpıyordu.",
      "Kemal kalbinde tatlı bir çekim hissetti. Sanki yıldız onu bir maceraya davet ediyor, daha yakına gelmesini fısıldıyordu. Bu büyülü ışıltıyı takip etmesi gerektiğini biliyordu.",
      "Yavaşça yataktan kalktı ve parmak uçlarında penceresine gitti. Dışarıdaki hava serin ve taze çim kokuyordu. Gökkuşağı yıldızı sanki onu bekliyordu.",
      "Dışarıda, yıldızın ışığı onu büyük tepeye doğru götürdü. Yürürken, yol hafif, renkli parıltılarla ışıldıyordu. Biraz gergin ama çoğunlukla heyecanlı hissediyordu.",
      "Tepenin zirvesine ulaştığında, gökkuşağı yıldızı tam tepesindeydi. Yavaşça gökyüzünde güzel bir ışık köprüsü oluşmaya başladı. Tepeden yıldızlara doğru uzanıyordu.",
      "\"Gökyüzü Köprüsü\" tüm gökkuşağı renkleriyle nazikçe parlıyordu. Kemal ona bakarken bir hayranlık titremesi hissetti. Muhteşem görünüyordu ama aynı zamanda çok yüksek ve çok yeniydi.",
      "Gerçekten yıldız ışığından yapılmış bir köprüde yürüyebilir miydi? Karnı biraz kelebeklendi. Tepede güvende kalmayı düşündü, ama köprü o kadar davetkar ve büyülü görünüyordu.",
      "Derin bir nefes alan Kemal, maceracı hayallerini hatırladı. Gökyüzü Köprüsü'ne cesur bir adım attı. Çıplak ayaklarının altında şaşırtıcı derecede sağlam ve ılık hissettirdi.",
