      "Kemal gözlerini kapattı, cesur macerasını hatırladı. Biliyordu ki bazen en harika keşifler, yeni bir şeyi denemeye cesaret ettiğinde gerçekleşirdi. Kısa süre sonra derin bir uykuya daldı, tatlı, yıldızlı rüyalar görüyordu."
