      "Nisan's eyes widened. A Secret Club! \"Yes, please!\" she said, feeling a flutter of excitement in her tummy.",
      "She quickly followed Ela and the others towards the big oak tree, which had a cozy little space underneath its branches. This must be their secret hideout!",
      "But as they got closer, Nisan noticed a little boy named Can sitting alone on a bench nearby, drawing in the dirt with a stick. He looked a bit sad.",
