      "Nisan looked at Can, then at the excited faces of the Secret Club members. A little cloud of worry floated over her happy feeling.",
      "She took a deep breath. \"Wait,\" Nisan said softly, letting go of Ayşe's hand. \"Maybe Can wants to play too. Our club could be even more fun with him.\"",
      "Ela and Ayşe looked surprised, then at Can. Can slowly looked up, his eyes wide with a tiny spark of hope.",
      "Nisan smiled brightly at Can. \"Come join us, Can! We can all explore the secret oak tree together!\" she called out.",
      "Can's face lit up like a summer sky. He quickly ran over, and soon, all the children were laughing and sharing their secret stories under the tree.",
      "Nisan felt a warm, bubbly feeling in her heart. Playing with everyone was the best secret of all.",
