      "Parlak kırmızı ayakkabılı Ela adında bir kız, Nisan'a el salladı. \"Nisan, bizim Gizli Kulübümüze katılmak ister misin?\" diye göz kırparak sordu.",
      "Nisan'ın gözleri büyüdü. Gizli Kulüp! \"Evet, lütfen!\" dedi, karnında kelebekler uçuşuyordu.",
