      "Ama daha da yaklaşırken, Nisan yakındaki bir bankta tek başına oturan, elindeki çubukla toprağa resim çizen küçük bir çocuk olan Can'ı fark etti. Biraz üzgün görünüyordu.",
      "\"Acele et, Nisan!\" diye fısıldadı başka bir kız, Ayşe, kolundan çekiştirerek. \"Kimsenin gizli yerimizi bulmasını istemeyiz.\"",
