      "Derin bir nefes aldı. \"Bekleyin,\" dedi Nisan yavaşça, Ayşe'nin elini bırakarak. \"Belki Can da oynamak ister. Kulübümüz onunla daha da eğlenceli olabilir.\"",
      "Ela ve Ayşe şaşkınlıkla baktılar, sonra Can'a döndüler. Can yavaşça başını kaldırdı, gözleri minicik bir umut kıvılcımıyla parlıyordu.",
      "Nisan, Can'a sımsıcak gülümsedi. \"Gel bize katıl, Can! Hepimiz gizli meşe ağacını birlikte keşfedebiliriz!\" diye seslendi.",
