    contentTr: [
      "Mete, rengarenk uçurtmasını çok severdi. Uzun, sallanan bir kuyruğu vardı. Güneşli ve rüzgarlı bir öğleden sonra, Mete özel uçurtmasını büyük yeşil parka götürdü.",
      "İpi sıkıca tuttu ve rüzgar uçurtmasını gökyüzüne, çok yükseklere kaldırdı. Uçurtma, neşeli bir kuş gibi dans ediyordu. Mete sevinçle güldü.",
      "Birden çok kuvvetli bir rüzgar esti. Fiuuu! Uçurtma sallandı ve döndü. Sonra hızla aşağı süzüldü.",
      "Eyvah! Uçurtma yumuşak bir çalılığa çarptı. Mete onu yerden aldığında, tam ortasında kocaman, yırtık bir yer gördü. Güzel uçurtması kırılmıştı.",
      "Mete'nin gözünden küçük bir damla yaş geldi. Mutlu uçurtması şimdi üzgündü. Bu kadar büyük bir yırtığı tek başına nasıl tamir edeceğini bilmiyordu.",
      "Tam o sırada arkadaşı Elif yanından geçti. \"Ne oldu Mete?\" diye nazikçe sordu. Mete ona kırık uçurtmasını gösterdi.",
      "Elif bir an düşündü. \"Üzülme Mete! Onu birlikte tamir edebiliriz,\" dedi parlak bir gülümsemeyle. \"İki el, tek elden iyidir!\"",
      "Mete'nin evine gittiler ve rengarenk bantlar, biraz yapıştırıcı ve çocuk makası aldılar. Uçurtmayı dikkatlice masaya yaydılar.",
      "Mete yırtığın kenarlarını tutarken, Elif nazikçe bant şeritlerini üzerine yapıştırdı. İyice bastırdılar, pürüzsüz olduğundan emin oldular. Hatta en zayıf görünen yere ekstra bant bile eklediler.",
      "Yavaşça, parça parça, yırtık kayboldu. Uçurtma, yeni rengarenk yamalarıyla daha da parlak görünüyordu! Çok sağlam ve eşsiz olmuştu.",
      "Tamir ettikleri uçurtmayı tekrar parka götürdüler. Bu sefer, daha yükseğe süzüldü ve eskisinden daha zarif dans etti. Birlikte tamir ettikleri için ekstra güçlü hissediyordu.",
      "Mete gülümsedi, içi sıcacık ve mutluydu. Arkadaşların birlikte çalıştığında, kırık şeylerin bile daha güçlü ve özel olabileceğini biliyordu. Şimdi, tüm bu eğlenceden yorgun düşen Mete, yatağına kıvrıldı ve ayın altında uçan uçurtmaların hayalini kurdu."
    ]
