      "Güneşli bir öğleden sonra, Bulut kendini biraz yorgun hissetti. Patileri ağırlaşmış, göz kapakları kapanmak istiyordu. Ama oynamaya devam etmek istiyordu.",
      "Anne Ayı, hareketli yavrusunun uykulu halini fark etti. Ona nazikçe sarıldı. \"Tatlı Bulut'um,\" diye fısıldadı, \"bugün farklı bir macera denemeye ne dersin?\"",
      "Bulut başını yana eğdi. \"Farklı bir macera mı?\" diye esnedi. Anne Ayı gülümsedi, \"Evet, sakin ve huzurlu bir macera.\"",
      "Birlikte, fısıldayan ağaçların arasından yavaşça yürüdüler. Bulut kuşların tatlı şarkılarını dinledi. Yaprakların nazikçe salınışını seyretti.",
      "Pırıl pırıl bir derenin kenarında özel bir yer buldular. Güneş, yumuşacık, yemyeşil bir yosun yamacına sıcacık vuruyordu. Tam bir yatak gibi görünüyordu.",
      "Bulut genellikle derede oynamak veya kelebekleri kovalamak isterdi. Ama bugün, vücudu çok ağırdı. Acaba sadece oturup dinlenmeli miydi?",
      "Davetkar yosunlara baktı. Çok yumuşak ve huzurlu görünüyordu. Bulut yeni bir şey denemeye karar verdi.",
      "Yosunların üzerine dikkatlice uzandı, tüylerine değen serinliği hissetti. Güneşin ılık ışınları burnunu okşadı. Gözlerini kapattı ve derin, yavaş bir nefes aldı.",
      "Harika bir sakinlik hissetti. Bulut fark etti ki bazen dinlenmek, oynamak kadar hatta daha da iyi hissettiriyordu. Uyumaya başladı.",
      "Bulut uyandığında, kendini harika hissetti, tazelenmiş ve her şeye hazırdı. Patileri hafiflemiş, gözleri parlıyordu. Dinlenmek ona yepyeni bir enerji vermişti.",
      "Bulut o gece yatağına kıvrıldı. Sakin macerasını ve sadece hareketsiz kalmanın ne kadar iyi hissettirdiğini düşündü. Çok geçmeden, mışıl mışıl uykuya daldı, huzurlu rüyalar gördü."
