      "\"Eyvah,\" diye cıvıldadı minik, parıldayan bir ateşböceği, Yusuf'un yanına uçarak. \"Büyük Yanardağ bugün üzgün. Bu yüzden ada sallanıyor.\"",
      "Yusuf, tepesinden küçük duman bulutları çıkan koca yanardağa baktı. \"Onu nasıl mutlu edebiliriz?\" diye sordu ateşböceğine.",
