      "Ateşböceği Yusuf'a minik, parlayan bir çakıl taşı verdi. \"Bu sana yolu gösterecek, ama uğultu daha da artsa bile sakin kalmalısın.\"",
      "Yusuf cesurca çakıl taşının nazik ışığını takip ederek sessiz bir mağaraya girdi. Yer yine sallandı, bu sefer biraz daha güçlü.",
